// @generated by:gauntlet run:godseye-local-broker
import { randomUUID } from "node:crypto";
import { createServer, type ServerResponse } from "node:http";
import { afterEach, describe, expect, it } from "vitest";
import type { AccessScope } from "../packages/core/src/access-provider.js";
import { BAO_BROKER_POLICY, compileBrokerPolicy } from "../packages/core/src/bao-policy.js";
import { BaoAccessProvider } from "../packages/core/src/bao-provider.js";

const target: AccessScope = {
  projectId: randomUUID(),
  environmentId: randomUUID(),
  purpose: "runtime",
  id: randomUUID(),
  slotId: randomUUID(),
};
const marker = randomUUID();
type FaultHandler = (response: ServerResponse) => void;
async function faultServer(fault: FaultHandler) {
  let redirectedCalls = 0;
  const server = createServer((request, response) => {
    response.setHeader("content-type", "application/json");
    const reply = (body: unknown) => response.end(JSON.stringify(body));
    switch (request.url) {
      case "/v1/sys/health":
        return reply({ initialized: true, sealed: false });
      case "/v1/auth/token/lookup-self":
        return reply({ data: { policies: [BAO_BROKER_POLICY] } });
      case `/v1/sys/policies/acl/${BAO_BROKER_POLICY}`:
        return reply({ data: { policy: compileBrokerPolicy() } });
      case "/redirected":
        redirectedCalls++;
        return reply({ unexpected: true });
      default:
        return fault(response);
    }
  });
  await new Promise<void>((accept) => server.listen(0, "127.0.0.1", accept));
  const address = server.address();
  if (!address || typeof address === "string") throw new Error("Fault fixture has no owned port");
  const origin = `http://127.0.0.1:${address.port}`;
  return {
    origin,
    redirectedCalls: () => redirectedCalls,
    async close() {
      server.closeAllConnections();
      await new Promise<void>((accept, reject) =>
        server.close((error) => (error ? reject(error) : accept())),
      );
    },
  };
}

/** Summarize only safe observable failures, so an unsafe upstream error cannot enter runner output. */
async function failure(work: () => Promise<unknown>) {
  try {
    await work();
    return { code: null, leaked: false };
  } catch (error) {
    const code = error && typeof error === "object" && "code" in error ? error.code : null;
    const message = error instanceof Error ? error.message : String(error);
    return { code, leaked: message.includes(marker) };
  }
}

describe("OpenBao transport fault containment (owned HTTP simulator, not provider qualification)", () => {
  let server: Awaited<ReturnType<typeof faultServer>> | undefined;
  afterEach(async () => {
    await server?.close();
    server = undefined;
  });
  const provider = () =>
    new BaoAccessProvider({ address: server?.origin ?? "", proof: () => marker, timeoutMs: 100 });

  it("T08 T34 refuses redirects before forwarding the controller authority", async () => {
    server = await faultServer((response) => {
      response.writeHead(302, { location: "/redirected" });
      response.end();
    });
    expect(await failure(() => provider().read(target))).toEqual({
      code: "PROVIDER_UNAVAILABLE",
      leaked: false,
    });
    expect(server.redirectedCalls()).toBe(0);
  });

  it("T08 T34 bounds an oversized provider response and hides its material", async () => {
    server = await faultServer((response) =>
      response.end(JSON.stringify({ marker, padding: "x".repeat(70_000) })),
    );
    expect(await failure(() => provider().read(target))).toEqual({
      code: "PROVIDER_UNAVAILABLE",
      leaked: false,
    });
  });

  it("T08 T34 sanitizes malformed provider JSON rather than reporting its body", async () => {
    server = await faultServer((response) => response.end(`malformed:${marker}`));
    expect(await failure(() => provider().read(target))).toEqual({
      code: "PROVIDER_UNAVAILABLE",
      leaked: false,
    });
  });

  it("T08 T23 times out an unresponsive read with a bounded safe failure", async () => {
    server = await faultServer(() => undefined);
    expect(await failure(() => provider().read(target))).toEqual({
      code: "PROVIDER_UNAVAILABLE",
      leaked: false,
    });
  });

  it("T08 T23 preserves uncertainty after a rejected write without exposing upstream material", async () => {
    server = await faultServer((response) => {
      response.writeHead(502);
      response.end(JSON.stringify({ errors: [marker] }));
    });
    expect(
      await failure(() =>
        provider().write(
          target,
          {
            value: marker,
            operationId: randomUUID(),
            fingerprint: "a".repeat(64),
          },
          0,
        ),
      ),
    ).toEqual({ code: "PROVIDER_UNKNOWN", leaked: false });
  });
});
